        metrics.timespan.crash_time_since_last_crash.value
      ) AS `crash_time_since_last_crash`,
      STRUCT(
        metrics.timespan.crash_install_time.time_unit,
        metrics.timespan.crash_install_time.value
      ) AS `crash_install_time`
    ) AS `timespan`,
    STRUCT(
      metrics.object.crash_async_shutdown_timeout,
      metrics.object.crash_breadcrumbs,
      metrics.object.crash_java_exception,
      metrics.object.crash_quota_manager_shutdown_timeout,
      metrics.object.crash_stack_traces,
      metrics.object.meta_annotations
    ) AS `object`,
    STRUCT(
      metrics.quantity.crash_event_loop_nesting_level,
      metrics.quantity.crash_gpu_process_launch,
      metrics.quantity.memory_available_commit,
      metrics.quantity.memory_available_physical,
      metrics.quantity.memory_available_swap,
      metrics.quantity.memory_available_virtual,
      metrics.quantity.memory_low_physical,
      metrics.quantity.memory_oom_allocation_size,
      metrics.quantity.memory_purgeable_physical,
      metrics.quantity.memory_system_use_percentage,
      metrics.quantity.memory_texture,
      metrics.quantity.memory_total_page_file,
      metrics.quantity.memory_total_physical,
      metrics.quantity.memory_total_virtual
    ) AS `quantity`,
    STRUCT(
      metrics.string_list.environment_experimental_features,
      metrics.string_list.glean_ping_uploader_capabilities,
      metrics.string_list.crash_utility_actors_name,
      metrics.string_list.dll_blocklist_list,
      metrics.string_list.environment_nimbus_enrollments
    ) AS `string_list`
  ) AS `metrics`,
  normalized_app_name,
  normalized_country_code,
  normalized_os,
  normalized_os_version,
  STRUCT(
    ping_info.end_time,
    ARRAY(
      SELECT
        STRUCT(
          experiments.key,
          STRUCT(
            experiments.value.branch,
            STRUCT(experiments.value.extra.type, experiments.value.extra.enrollment_id) AS `extra`
          ) AS `value`
        )
      FROM
        UNNEST(ping_info.experiments) AS `experiments`
    ) AS `experiments`,
    ping_info.ping_type,
    ping_info.reason,
    ping_info.seq,
    ping_info.start_time,
    STRUCT(
      ping_info.server_knobs_config.event_threshold,
      ARRAY(
        SELECT
          STRUCT(metrics_enabled.key, metrics_enabled.value)
        FROM
          UNNEST(ping_info.server_knobs_config.metrics_enabled) AS `metrics_enabled`
      ) AS `metrics_enabled`,
      ARRAY(
        SELECT
          STRUCT(pings_enabled.key, pings_enabled.value)
        FROM
          UNNEST(ping_info.server_knobs_config.pings_enabled) AS `pings_enabled`
      ) AS `pings_enabled`,
      ping_info.server_knobs_config.session_sample_rate
    ) AS `server_knobs_config`
  ) AS `ping_info`,
  sample_id,
  submission_timestamp,
FROM
  `moz-fx-data-shared-prod.org_mozilla_focus_nightly_live.crash_v1`
